import time
from functools import wraps

def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"함수 '{func.__name__}' 실행 시간: {end - start:.6f} 초")
        return result
    return wrapper

@timer
def sum_numbers(a, b):
    return a + b

sum_numbers(10, 20)
