```python
from functools import wraps

def retry(max_attempts=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except ZeroDivisionError as e:
                    print(f"ZeroDivisionError 발생 (시도 {attempt}/{max_attempts}): {e}")
                    if attempt == max_attempts:
                        raise
        return wrapper
    return decorator

@retry()
def calculate():
    x = 10
    y = 0
    result = x / y
    print(f"결과: {result}")

try:
    calculate()
except ZeroDivisionError as e:
    print("최종 예외 처리:", str(e))
```

